assignments.value:
={{ (() => {
  const p = $json.candidate_profile;
  const criteria = [
    { id: 'sales_experience', name: 'Kinh nghiệm Sales/CS có KPI', score: p.months_sales >= 24 ? 20 : p.months_sales >= 12 ? 16 : p.months_sales >= 6 ? 10 : 0, max_points: 20, evidence: p.evidence.months_sales || '', scoring_note: 'Chấm theo số tháng Sales.' },
    { id: 'b2b_experience', name: 'Kinh nghiệm B2B', score: p.months_b2b >= 24 ? 15 : p.months_b2b >= 12 ? 12 : p.months_b2b >= 6 ? 8 : 0, max_points: 15, evidence: p.evidence.months_b2b || '', scoring_note: 'Chấm theo số tháng B2B.' },
    { id: 'prospecting', name: 'Tìm kiếm và tiếp cận khách hàng', score: Math.min((p.prospecting_channels || []).length * 5, 15), max_points: 15, evidence: p.evidence.prospecting_channels || '', scoring_note: '5 điểm mỗi kênh, tối đa 15.' },
    { id: 'communication', name: 'Tư vấn, giao tiếp và đàm phán', score: p.communication_evidence ? 12 : 0, max_points: 15, evidence: p.communication_evidence || '', scoring_note: 'Có evidence rõ được 12 điểm.' },
    { id: 'crm_pipeline', name: 'CRM và quản lý pipeline', score: (p.crm_tools || []).length ? 10 : 0, max_points: 10, evidence: p.evidence.crm_tools || '', scoring_note: 'Có CRM và evidence được 10 điểm.' },
    { id: 'quantified_achievement', name: 'Thành tích có số liệu', score: p.quantified_achievement ? 15 : 0, max_points: 15, evidence: p.quantified_achievement || '', scoring_note: 'Có kết quả định lượng được 15 điểm.' },
    { id: 'market_fit', name: 'Hiểu thị trường liên quan', score: (p.market_experience || []).length ? 5 : 0, max_points: 5, evidence: (p.market_experience || []).join(', '), scoring_note: 'Có thị trường liên quan được 5 điểm.' },
    { id: 'tools_and_cv_quality', name: 'Công cụ và chất lượng CV', score: (p.office_tools || []).length >= 2 ? 5 : (p.office_tools || []).length === 1 ? 3 : 0, max_points: 5, evidence: (p.office_tools || []).join(', '), scoring_note: 'Hai công cụ trở lên được 5 điểm.' }
  ];
  const total_score = criteria.reduce((sum, item) => sum + item.score, 0);
  const result = !$json.data_quality.ready_for_scoring ? 'NEEDS_REVIEW' : total_score >= 75 ? 'STRONG_REVIEW' : total_score >= 60 ? 'REVIEW' : 'LOW_PRIORITY_REVIEW';
  const interview_questions = [
    'Bạn có thể mô tả một tình huống thực tế khi tìm kiếm và chuyển đổi khách hàng B2B thành cuộc hẹn?',
    p.quantified_achievement ? 'Thành tích ' + p.quantified_achievement + ' được tính trên chỉ tiêu nào và vai trò trực tiếp của bạn là gì?' : 'Bạn có thể cung cấp một kết quả bán hàng định lượng gần đây?',
    (p.crm_tools || []).length ? 'Bạn đã dùng ' + p.crm_tools.join(', ') + ' để quản lý pipeline và follow-up như thế nào?' : 'Bạn đã quản lý pipeline và hoạt động follow-up bằng công cụ hoặc phương pháp nào?'
  ];
  return { source_candidate_id: p.candidate_id, criteria, total_score, result, human_review_required: true, scoring_summary: 'Điểm theo rubric cố định; HR phải duyệt.', interview_questions };
})() }}
